head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > validator]<br/>컴포넌트의 날짜 편집 영역에서 포커스가 해제될때 입력값 검증을 처리할 사용자 정의 함수를 설정합니다.",
    "validation" : [      
        "사용자 정의 함수가 수행된 후 onblur 이벤트가 발생합니다.",
        "컴포넌트의 입력값이 변경되면 onchange -> onviewchange -> onblur 순으로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        validator: con_validator.getText(),
        editType : "select"
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onblur"]);

    $c.gcm.createLabel('label="년도가 2000 년도 보다 작거나 2030 년도 보다 큰 경우 validaotor 에 의해 2000 년도로 설정됨"', '', 'label1');
    $c.gcm.createBasicInputCalendar(cList, eList);
}



// 특정 연도로 변환하는 사용자 정의 함수
scwin.fn_validator = function(val, id) { 
    wf_body_bottom.getObj("scwin").setReturnValue("전달 파라미터 : " + val + ", " + id); 

    let year = parseInt(val.slice(0, 4), 10);
    const day = val.slice(4);

    if (year < 2000 || year > 2030)
        return "2000" + day;
    else
        return val;
}



scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange====="); 
}



scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange====="); 
}


scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur====="); 
}
